#!/usr/bin/env node
import { cpSync, mkdirSync, rmSync } from 'node:fs';

const destination = '.pages-dist';
rmSync(destination, { recursive: true, force: true });
mkdirSync(destination, { recursive: true });
for (const file of [
  'index.html',
  'app.js',
  'styles.css',
  'theme.css',
  'service-worker.js',
  'diagnostics-ui.js',
  'manifest.webmanifest',
  'shopcrank-icon.svg',
]) cpSync(file, `${destination}/${file}`);
cpSync('assets', `${destination}/assets`, { recursive: true });
cpSync('public', destination, { recursive: true });
try {
  cpSync('downloads', `${destination}/downloads`, { recursive: true });
} catch {
  mkdirSync(`${destination}/downloads`, { recursive: true });
}
console.log(`Staged Cloudflare Pages assets in ${destination}`);

#!/usr/bin/env node
import * as esbuild from 'esbuild';
import { existsSync } from 'node:fs';
import { dirname, join } from 'node:path';
import { fileURLToPath } from 'node:url';

const root = join(dirname(fileURLToPath(import.meta.url)), '..');
const watch = process.argv.includes('--watch');

/** @type {import('esbuild').BuildOptions} */
const options = {
  entryPoints: [join(root, 'src/main.js')],
  outfile: join(root, 'app.js'),
  bundle: true,
  format: 'iife',
  platform: 'browser',
  target: ['es2020'],
  legalComments: 'none',
  logLevel: 'info',
  // Root app.js is a build artifact — edit src/ and run npm run build:web.
  banner: {
    js: '/* GENERATED by scripts/build-web.mjs from src/ — do not edit app.js directly */',
  },
};

if (!existsSync(options.entryPoints[0])) {
  console.error('Missing entry:', options.entryPoints[0]);
  process.exit(1);
}

if (watch) {
  const ctx = await esbuild.context(options);
  await ctx.watch();
  console.log('Watching src/ → app.js');
} else {
  await esbuild.build(options);
}

#!/usr/bin/env node
import { existsSync, readFileSync, writeFileSync } from 'node:fs';
import { dirname, join } from 'node:path';
import { fileURLToPath } from 'node:url';

const root = join(dirname(fileURLToPath(import.meta.url)), '..');
const configFile = join(root, 'src/shared/config.js');
const apiUrl = String(process.env.SHOP_CRANK_API_URL || '/api').replace(/\/$/, '') || '/api';
const next = `/**
 * Shared Shop Crank client configuration.
 * Generated by scripts/sync-frontend-config.mjs — do not edit by hand.
 * Source: SHOP_CRANK_API_URL (defaults to same-origin /api)
 */
export const cloudflareConfig = Object.freeze({
  auth: 'shopcrank-saas',
  apiUrl: ${JSON.stringify(apiUrl)},
  authEndpoints: {
    magicLink: ${JSON.stringify(apiUrl + '/auth/magic-link')},
    callback: ${JSON.stringify(apiUrl + '/auth/callback')},
    session: ${JSON.stringify(apiUrl + '/auth/session')},
    logout: ${JSON.stringify(apiUrl + '/auth/logout')},
  },
});

export const storageKeys = Object.freeze({
  dispatch: 'shopcrank-dispatch-v1',
  session: 'shopcrank-session',
  mutationQueue: 'shopcrank-mutation-queue-v1',
});

if (typeof globalThis !== 'undefined') {
  globalThis.__SHOP_CRANK_CONFIG__ = { cloudflare: cloudflareConfig, storage: storageKeys };
}
`;

if (existsSync(configFile) && readFileSync(configFile, 'utf8') === next) {
  console.log('config.js already up to date (Cloudflare same-origin defaults)');
} else {
  writeFileSync(configFile, next);
  console.log(`Wrote ${configFile}`);
}

