'use strict';

const fs = require('node:fs');
const path = require('node:path');

function isPackagedApp() {
  try {
    return Boolean(require('electron').app?.isPackaged);
  } catch {
    return false;
  }
}

function publicKeyCandidates() {
  const candidates = [];
  if (process.resourcesPath) {
    candidates.push(path.join(process.resourcesPath, 'diagnostics-keys', 'capability-public-key.pem'));
    candidates.push(path.join(process.resourcesPath, 'capability-public-key.pem'));
  }
  candidates.push(path.join(__dirname, '..', 'diagnostics', 'keys', 'local-capability-public-key.pem'));
  candidates.push(path.join(__dirname, '..', 'diagnostics', 'keys', 'capability-public-key.pem'));
  return candidates;
}

function readFile(filePath) {
  try {
    if (!fs.existsSync(filePath)) return '';
    return String(fs.readFileSync(filePath, 'utf8') || '').trim();
  } catch {
    return '';
  }
}

/**
 * Resolve the ECDSA P-256 PUBLIC key used to VERIFY Worker-issued capability
 * tokens. Only the public key ships with the client — it cannot mint tokens —
 * which removes the previous risk of a shared signing secret in the installer.
 * Missing keys must not block read-only J2534 operations.
 */
function resolveDiagnosticsPublicKey(options = {}) {
  const env = options.env || process.env;
  const fromEnv = String(env.DIAGNOSTICS_SIGNING_PUBLIC_KEY || '').trim();
  if (fromEnv) return { publicKey: fromEnv, source: 'env' };

  for (const candidate of publicKeyCandidates()) {
    const fromFile = readFile(candidate);
    if (fromFile) return { publicKey: fromFile, source: candidate };
  }

  return { publicKey: '', source: (options.packaged ?? isPackagedApp()) ? 'missing-packaged' : 'missing-dev' };
}

module.exports = { resolveDiagnosticsPublicKey };

'use strict';

const { describe, it } = require('node:test');
const assert = require('node:assert/strict');
const fs = require('node:fs');
const os = require('node:os');
const path = require('node:path');
const { DEV_FALLBACK_SECRET, resolveDiagnosticsCapabilitySecret } = require('./diagnostics-secrets');

describe('resolveDiagnosticsCapabilitySecret', () => {
  it('prefers environment variables', () => {
    const result = resolveDiagnosticsCapabilitySecret({
      env: { SHOP_CRANK_DIAG_CAPABILITY_SECRET: ' from-env ' },
      packaged: true,
    });
    assert.equal(result.secret, 'from-env');
    assert.equal(result.source, 'env');
  });

  it('uses the packaged secret file when present', () => {
    const dir = fs.mkdtempSync(path.join(os.tmpdir(), 'shopcrank-diag-secret-'));
    const filePath = path.join(dir, 'capability-secret.txt');
    fs.writeFileSync(filePath, 'packaged-secret\n');
    const previous = process.resourcesPath;
    process.resourcesPath = dir;
    try {
      // Place where packagedSecretCandidates looks first: resources/diagnostics-secrets/
      const nested = path.join(dir, 'diagnostics-secrets');
      fs.mkdirSync(nested);
      fs.writeFileSync(path.join(nested, 'capability-secret.txt'), 'nested-packaged-secret\n');
      const result = resolveDiagnosticsCapabilitySecret({ env: {}, packaged: true });
      assert.equal(result.secret, 'nested-packaged-secret');
      assert.match(result.source, /capability-secret\.txt$/);
    } finally {
      if (previous === undefined) delete process.resourcesPath;
      else process.resourcesPath = previous;
      fs.rmSync(dir, { recursive: true, force: true });
    }
  });

  it('does not throw when packaged secret is missing', () => {
    const result = resolveDiagnosticsCapabilitySecret({ env: {}, packaged: true });
    assert.equal(result.secret, '');
    assert.equal(result.source, 'missing-packaged');
  });

  it('falls back to the shared dev secret for unpackaged builds', () => {
    const result = resolveDiagnosticsCapabilitySecret({ env: {}, packaged: false });
    assert.equal(result.secret, DEV_FALLBACK_SECRET);
    assert.equal(result.source, 'dev-fallback');
  });
});

